#include <print>
#include <set>
#include <vector>
#include <functional>

int main() {
    std::vector<int> nums = {5, 3, 8, 3, 5, 1, 8, 9};
    std::set<int> unique_nums(nums.begin(), nums.end());
    std::set<int> a = {5, 3, 8, 3, 5, 1};
    std::set<int> b = {8, 9, 3, 12, 3};
    for (int v : a)
        if (b.contains(v)) std::print("{} ", v);
    std::println("");
    auto r1 = a.insert(3);
    std::println("再塞 3：收下 = {}", r1.second);
    std::set<int, std::greater<int>> desc = {5, 3, 8, 3, 1};
    for (int v : desc) std::print("{} ", v);
    std::println("");
    return 0;
}

